// ─── File: LoadBalancerDemo.java ───
// Runnable demo. Each class would be its own file in a real project.
package com.bank.lb;

import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.logging.*;

public class LoadBalancerDemo {
    private static final Logger log = Logger.getLogger(LoadBalancerDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        List<Backend> backends = new ArrayList<>(List.of(
                new Backend("transfer-svc-1:8080", 1),
                new Backend("transfer-svc-2:8080", 1),
                new Backend("transfer-svc-3:8080", 2)));
        RoundRobinLoadBalancer rr = new RoundRobinLoadBalancer(backends);

        // Scenario 1: 9 concurrent transfer requests spread evenly (round-robin)
        Map<String, Integer> counts = new ConcurrentHashMap<>();
        ExecutorService pool = Executors.newFixedThreadPool(9);
        CountDownLatch start = new CountDownLatch(1);
        List<Future<?>> futures = new ArrayList<>();
        for (int i = 0; i < 9; i++) {
            futures.add(pool.submit(() -> {
                try { start.await(); } catch (InterruptedException ignored) { }
                Backend b = rr.next();
                counts.merge(b.address, 1, Integer::sum);
            }));
        }
        start.countDown();
        for (Future<?> f : futures) f.get();
        pool.shutdown();
        log.info("Even distribution over 9 requests: " + counts);

        // Scenario 2: mark svc-2 unhealthy → it is skipped
        backends.get(1).healthy = false;
        Map<String, Integer> counts2 = new TreeMap<>();
        for (int i = 0; i < 6; i++) {
            Backend b = rr.next();
            counts2.merge(b.address, 1, Integer::sum);
        }
        log.info("After svc-2 down (skipped): " + counts2);

        // Scenario 3: weighted round-robin — svc-3 (weight 2) gets double share
        backends.get(1).healthy = true;
        WeightedRoundRobinLoadBalancer wrr = new WeightedRoundRobinLoadBalancer(backends);
        Map<String, Integer> counts3 = new TreeMap<>();
        for (int i = 0; i < 8; i++) {
            Backend b = wrr.next();
            counts3.merge(b.address, 1, Integer::sum);
        }
        log.info("Weighted over 8 requests (svc-3 weight=2): " + counts3);
    }
}

// ─── core/Backend.java ───
class Backend {
    final String address; final int weight; volatile boolean healthy = true;
    Backend(String address, int weight) { this.address = address; this.weight = weight; }
}

// ─── core/LoadBalancer.java ───
interface LoadBalancer {
    Backend next();   // returns the backend to route the next request to
}

// ─── core/RoundRobinLoadBalancer.java ───
// Lock-free round-robin using AtomicInteger + floorMod. Skips unhealthy nodes.
class RoundRobinLoadBalancer implements LoadBalancer {
    private final List<Backend> backends;
    private final AtomicInteger counter = new AtomicInteger(0);
    RoundRobinLoadBalancer(List<Backend> backends) { this.backends = backends; }

    public Backend next() {
        int size = backends.size();
        // Try up to 'size' positions to find a healthy backend.
        for (int attempt = 0; attempt < size; attempt++) {
            // getAndIncrement is atomic: each concurrent caller gets a distinct tick.
            // floorMod keeps the index non-negative even after int overflow.
            int index = Math.floorMod(counter.getAndIncrement(), size);
            Backend b = backends.get(index);
            if (b.healthy) return b;
        }
        throw new IllegalStateException("no healthy backend available");
    }
}

// ─── core/WeightedRoundRobinLoadBalancer.java ───
// Simple weighted RR: expand the list so a weight-w backend appears w times,
// then round-robin over the expanded list with the same AtomicInteger trick.
class WeightedRoundRobinLoadBalancer implements LoadBalancer {
    private final List<Backend> expanded = new ArrayList<>();
    private final AtomicInteger counter = new AtomicInteger(0);
    WeightedRoundRobinLoadBalancer(List<Backend> backends) {
        for (Backend b : backends)
            for (int i = 0; i < b.weight; i++) expanded.add(b);  // weight-2 appears twice
    }
    public Backend next() {
        int size = expanded.size();
        for (int attempt = 0; attempt < size; attempt++) {
            int index = Math.floorMod(counter.getAndIncrement(), size);
            Backend b = expanded.get(index);
            if (b.healthy) return b;
        }
        throw new IllegalStateException("no healthy backend available");
    }
}

